function build(api) {
  api.name('Wind Chime');

  const C_HOOK = 0x1a5c2a;
  const C_STEM = 0x88c070;
  const C_LEAF = 0x3cb371;
  const C_VEIN = 0x2a8b57;
  const C_LINE = 0x88c070;
  const C_BELL = 0xdaa520;

  // Hook
  api.group('hook', 'hook');
    api.torus({r:0.2, tube:0.05, along:'+Y', pos:[0, 7.5, 0], color:C_HOOK});
  api.endGroup();

  // Stem
  api.group('stem', 'stem');
    api.chain({waypoints:[[0, 7.3, 0], [0, 6.5, 0.1], [0, 5.5, -0.1], [0, 4.5, 0]], r:0.12, rEnd:0.08, color:C_STEM});
  api.endGroup();

  // Main Body
  api.group('main_body', 'main_body');
    // Volume blocks: Layered leaves
    api.patch({points:[[0, 4.5, 0], [-1.2, 3.8, 0.2], [-0.8, 2.8, 0.1], [0, 2.5, 0]], d:0.08, color:C_LEAF});
    api.patch({points:[[0, 4.5, 0], [1.2, 3.8, -0.2], [0.8, 2.8, -0.1], [0, 2.5, 0]], d:0.08, color:C_LEAF});
    api.patch({points:[[0, 4.5, 0], [0.2, 3.8, 1.2], [-0.1, 2.8, 0.8], [0, 2.5, 0]], d:0.08, color:C_LEAF});
    api.patch({points:[[0, 4.5, 0], [-0.2, 3.8, -1.2], [0.1, 2.8, -0.8], [0, 2.5, 0]], d:0.08, color:C_LEAF});

    // Smaller inner leaves
    api.patch({points:[[0, 4.2, 0], [-0.6, 3.6, 0.1], [-0.4, 3.0, 0.05], [0, 2.8, 0]], d:0.06, color:C_VEIN});
    api.patch({points:[[0, 4.2, 0], [0.6, 3.6, -0.1], [0.4, 3.0, -0.05], [0, 2.8, 0]], d:0.06, color:C_VEIN});
    api.patch({points:[[0, 4.2, 0], [0.1, 3.6, 0.6], [-0.05, 3.0, 0.4], [0, 2.8, 0]], d:0.06, color:C_VEIN});
    api.patch({points:[[0, 4.2, 0], [-0.1, 3.6, -0.6], [0.05, 3.0, -0.4], [0, 2.8, 0]], d:0.06, color:C_VEIN});

    // Veins (thin color patches on surface)
    api.tri({a:[0, 4.5, 0], b:[-0.9, 3.3, 0.15], c:[0, 2.5, 0], d:0.02, color:C_VEIN});
    api.tri({a:[0, 4.5, 0], b:[0.9, 3.3, -0.15], c:[0, 2.5, 0], d:0.02, color:C_VEIN});
    api.tri({a:[0, 4.5, 0], b:[0.15, 3.3, 0.9], c:[0, 2.5, 0], d:0.02, color:C_VEIN});
    api.tri({a:[0, 4.5, 0], b:[-0.15, 3.3, -0.9], c:[0, 2.5, 0], d:0.02, color:C_VEIN});
  api.endGroup();

  // Bells
  api.group('bells', 'bells');
    // Central bell
    api.chain({waypoints:[[0, 2.5, 0], [0, 1.8, 0]], r:0.03, color:C_LINE});
    api.cone({r:0.2, h:0.4, along:'-Y', pos:[0, 1.6, 0], color:C_BELL});
    api.poly({r:0.08, pos:[0, 1.35, 0], color:C_BELL});

    // Front bell
    api.chain({waypoints:[[0, 2.5, 0], [0.2, 1.5, 0.6], [0.1, 1.0, 0.8]], r:0.03, color:C_LINE});
    api.cone({r:0.15, h:0.3, along:'-Y', pos:[0.1, 0.85, 0.8], color:C_BELL});
    api.poly({r:0.06, pos:[0.1, 0.65, 0.8], color:C_BELL});

    // Back bell
    api.chain({waypoints:[[0, 2.5, 0], [-0.2, 1.5, -0.6], [-0.1, 1.0, -0.8]], r:0.03, color:C_LINE});
    api.cone({r:0.15, h:0.3, along:'-Y', pos:[-0.1, 0.85, -0.8], color:C_BELL});
    api.poly({r:0.06, pos:[-0.1, 0.65, -0.8], color:C_BELL});

    // Left bell
    api.chain({waypoints:[[0, 2.5, 0], [-0.7, 1.6, 0.1], [-1.0, 1.1, 0.1]], r:0.03, color:C_LINE});
    api.cone({r:0.15, h:0.3, along:'-Y', pos:[-1.0, 0.95, 0.1], color:C_BELL});
    api.poly({r:0.06, pos:[-1.0, 0.75, 0.1], color:C_BELL});

    // Right bell
    api.chain({waypoints:[[0, 2.5, 0], [0.7, 1.6, -0.1], [1.0, 1.1, -0.1]], r:0.03, color:C_LINE});
    api.cone({r:0.15, h:0.3, along:'-Y', pos:[1.0, 0.95, -0.1], color:C_BELL});
    api.poly({r:0.06, pos:[1.0, 0.75, -0.1], color:C_BELL});
  api.endGroup();
}
